# RW2DM_LAYERS: ChangeLayer, ChangeToCurrentLayer, CopyToLayer, MatchLayer, SetLayerToObject. The script rw2dm_layers_script.txt is generated by rw2dm_gen.py. The oracle is exact set / string logic on four objects (ids 1..4 = Point, Line, Plane, Box):
# after each step the objects that List reaches are compared, as id:kind:layer[:name], with the expected list exactly (and the printed message lines with their patterns).
RW2_LAYERS_OUT=""
if [ -n "${DISPLAY:-}" ] && xset q >/dev/null 2>&1 || ! command -v xvfb-run >/dev/null 2>&1; then
  RW2_LAYERS_OUT="$(timeout 900 "$BIN" --smoke 60 --script "$HERE/rw2dm_layers_script.txt" 2>&1)" || { echo "$RW2_LAYERS_OUT" | tail -40; echo "FAIL RW2DM_LAYERS_run: script exited non-zero"; fail=1; RW2_LAYERS_OUT=""; }
else
  RW2_LAYERS_OUT="$(timeout 900 xvfb-run -a -s "-screen 0 1600x900x24" "$BIN" --smoke 60 --script "$HERE/rw2dm_layers_script.txt" 2>&1)" || { echo "$RW2_LAYERS_OUT" | tail -40; echo "FAIL RW2DM_LAYERS_run: script exited non-zero"; fail=1; RW2_LAYERS_OUT=""; }
fi
rw2_layers_block() { awk -v name="$1" '$0 ~ ("Unknown command: RW2BEGIN_" name "$") { on = 1; next } on && /Unknown command: RW2BEGIN_/ { exit } on { print }' <<<"$RW2_LAYERS_OUT"; }
# rw2_layers_state STEP EXPECTED DESC [PATTERN...]: the objects listed in the step read exactly EXPECTED ("-" = none); each PATTERN must match a printed line of the step
rw2_layers_state() {
  local blk got name desc pat bad want; name="$1"; want="$2"; desc="$3"; blk="$(rw2_layers_block "$name")"
  got="$({ grep -E '^history: Object [0-9]+ \(' <<<"$blk" || true; } | sed -E "s/^history: Object ([0-9]+) \(([^)]*)\) layer ([^ ]+) name '(.*)'\$/\1:\2:\3:\4/; s/^history: Object ([0-9]+) \(([^)]*)\) layer ([^ ]+)\$/\1:\2:\3/" | tr '\n' ' ' | sed 's/ $//')"; [ -n "$got" ] || got="-"
  bad=""
  shift 3
  for pat in "$@"; do grep -qE "^history: $pat" <<<"$blk" || bad="$bad [$pat]"; done
  if [ "$got" = "$want" ] && [ -z "$bad" ]; then echo "ok   RW2DM_LAYERS_$name: $desc (objects: $got)"
  else echo "FAIL RW2DM_LAYERS_$name: $desc (listed '$got', expected '$want'; missing message patterns:${bad:- none})"; fail=1; { grep -E '^history: (Object|!|[A-Za-z]+:)' <<<"$blk" || true; } | head -14 | sed 's/^/     line: /'; fi
}
rw2_layers_state changelayer "1:point:A 2:curve:Default 3:surface:A 4:polysurface:Default" "ChangeLayer of 1 and 3 to layer A moves exactly those two (point and plane); 2 and 4 stay on Default" "Moved 2 object\(s\) to A"
rw2_layers_state changelayer_new "1:point:A 2:curve:Default 3:surface:A 4:polysurface:Z" "ChangeLayer to a layer that does not exist yet creates it: 4 goes to Z" "Moved 1 object\(s\) to Z"
rw2_layers_state tocurrent "1:point:A 2:curve:B 3:surface:A 4:polysurface:B" "after SetLayer B, ChangeToCurrentLayer of 2 and 4 moves them to B (1 and 3 stay on A)" 
rw2_layers_state copytolayer "1:point:A 2:curve:B 3:surface:A 4:polysurface:B 5:point:C 6:curve:C" "CopyToLayer of 1 and 2 to layer C copies both (ids 5 and 6 on C) and leaves the originals where they are" "CopyToLayer: 2 object\(s\) copied to C"
rw2_layers_state match "1:point:A 2:curve:A 3:surface:A 4:polysurface:B 5:point:C 6:curve:C" "MatchLayer of 1, 2 and 3 (the last, 3, is the layer to match: A) moves 2 to A as well; 4 stays on B" 
rw2_layers_state setlayertoobject "1:point:A 2:curve:A 3:surface:A 4:polysurface:B 5:point:C 6:curve:C 7:point:C" "SetLayerToObject on 6 (layer C) makes C the current layer: a new Point (id 7) lands on C" "Current layer: C"
